notes:
Added Spotless (ktlint 1.8.0) as a new G-FMT gate for Android only, per the user's request after they flagged the codebase had no formatting standard (UiState placement, nested functions, indentation all inconsistent). Scoped the ruleset deliberately narrow: disabled the whole ktlint 'standard' set, then re-enabled only indent/whitespace/spacing-related rules (indent, final-newline, no-trailing-whitespaces, no-multi-spaces, no-consecutive-blank-lines, no-blank-line-before-rbrace, no-empty-first-line-in-class-body, no-leading-empty-lines-in-method-blocks, spacing, no-semicolons, string-template-indent) rather than ktlint's full opinionated default (which forces trailing commas, function-signature line-wrapping, and would have produced a much larger, unrequested diff). Discovered along the way that a plain root .editorconfig file is NOT picked up by Spotless's ktlint step for per-rule overrides (confirmed empirically: three different .editorconfig rewrites produced an identical violation set) - the working config lives in an editorConfigOverride map in app/build.gradle.kts; kept a minimal .editorconfig for IDE-level hints only, documented the discrepancy in conventions.md so nobody wastes time on the same dead end. Ran spotlessApply across the whole existing app/ codebase to backfill (67 files, verified via diff --git a/app/build.gradle.kts b/app/build.gradle.kts
index fbf0e99..1d60c6b 100644
--- a/app/build.gradle.kts
+++ b/app/build.gradle.kts
@@ -6,6 +6,7 @@ plugins {
     alias(libs.plugins.kotlin.compose)
     alias(libs.plugins.hilt)
     alias(libs.plugins.ksp)
+    alias(libs.plugins.spotless)
 }

 val localProps = Properties().apply {
@@ -78,3 +79,36 @@ dependencies {
     kspAndroidTest(libs.hilt.compiler)
     androidTestImplementation(libs.androidx.test.runner)
 }
+
+// Scoped to whitespace/indentation/spacing, not a full house-style rewrite (trailing commas,
+// forced line-wrapping, naming conventions, brace insertion) — see the comment in .editorconfig.
+val ktlintEditorConfig = mapOf(
+    "ktlint_code_style" to "intellij_idea",
+    "max_line_length" to "off",
+    "ktlint_standard" to "disabled",
+    "ktlint_standard_indent" to "enabled",
+    "ktlint_standard_final-newline" to "enabled",
+    "ktlint_standard_no-trailing-whitespaces" to "enabled",
+    "ktlint_standard_no-multi-spaces" to "enabled",
+    "ktlint_standard_no-consecutive-blank-lines" to "enabled",
+    "ktlint_standard_no-blank-line-before-rbrace" to "enabled",
+    "ktlint_standard_no-empty-first-line-in-class-body" to "enabled",
+    "ktlint_standard_no-leading-empty-lines-in-method-blocks" to "enabled",
+    "ktlint_standard_spacing" to "enabled",
+    "ktlint_standard_no-semicolons" to "enabled",
+    "ktlint_standard_string-template-indent" to "enabled",
+)
+
+spotless {
+    kotlin {
+        target("src/**/*.kt")
+        targetExclude("**/build/**/*.kt")
+        ktlint("1.8.0").editorConfigOverride(ktlintEditorConfig)
+        trimTrailingWhitespace()
+        endWithNewline()
+    }
+    kotlinGradle {
+        target("*.gradle.kts")
+        ktlint("1.8.0").editorConfigOverride(ktlintEditorConfig)
+    }
+}
